  'cs.rubrics_help': 'ನಿಮ್ಮದೇ ರೇಟಿಂಗ್ ಮಾಪಕಗಳು. ನೀವು ತರಬೇತಿ ನೀಡುವ ಕ್ರೀಡೆಗಳ ಪ್ರಮಾಣಿತ ಮಾಪಕಗಳನ್ನು (FIFA, ICC, ಒಲಿಂಪಿಕ್ …) ನಿಮಗಾಗಿ ಸೇರಿಸಲಾಗುತ್ತದೆ — ಅವನ್ನು ಬದಲಿಸಿ, ಸೇರಿಸಿ ಅಥವಾ ಆರ್ಕೈವ್ ಮಾಡಿ. ಒಂದು ರೂಬ್ರಿಕ್ ಹಲವು ಕ್ರೀಡೆಗಳನ್ನು ಒಳಗೊಳ್ಳಬಹುದು, ಒಂದು ಕ್ರೀಡೆಗೆ ಹಲವು ರೂಬ್ರಿಕ್‌ಗಳಿರಬಹುದು. ಪ್ರತಿ ಅಂಕ ನೀಡಿದ ಆವೃತ್ತಿಯೊಂದಿಗೇ ಉಳಿಯುತ್ತದೆ, ಬೇರೆ ಬೇರೆ ಮಾಪಕಗಳ ಅಂಕಗಳನ್ನು ಎಂದಿಗೂ ಬೆರೆಸುವುದಿಲ್ಲ ಅಥವಾ ಅಧಿಕೃತ ಅಂಕಿಅಂಶವಾಗಿ ಪರಿವರ್ತಿಸುವುದಿಲ್ಲ.',
