  'setup.step.legal.t': 'ನಿಮ್ಮ ಕಾನೂನು ಹೆಸರು ಮತ್ತು ತೆರಿಗೆ ಸಂಖ್ಯೆ ಸೇರಿಸಿ',
  'setup.step.legal.w': 'ಇವು ಒಪ್ಪಂದಗಳು ಮತ್ತು ಇನ್‌ವಾಯ್ಸ್‌ಗಳಲ್ಲಿ ಕಾಣಿಸುತ್ತವೆ. ಮೊದಲ ದಿನದಿಂದಲೇ ಇನ್‌ವಾಯ್ಸ್‌ಗಳು ಮಾನ್ಯವಾಗಲು ನಿಮ್ಮ GST, VAT ಅಥವಾ ತೆರಿಗೆ ಸಂಖ್ಯೆ ಸೇರಿಸಿ.',
