  'setup.step.structure.t': 'ನಿಮ್ಮ ಮೊದಲ ತಂಡ ರಚಿಸಿ',
  'setup.step.structure.w': 'ತಂಡಗಳಲ್ಲಿ ನಿಮ್ಮ ರೋಸ್ಟರ್, ಲಭ್ಯತೆ ಮತ್ತು ಪಂದ್ಯಗಳಿರುತ್ತವೆ.',
