  'setup.step.people.w': 'TeamSnap, SportsEngine ಅಥವಾ ಸ್ಪ್ರೆಡ್‌ಶೀಟ್‌ನಿಂದ ನಿಮ್ಮ ರೋಸ್ಟರ್ ಆಮದು ಮಾಡಿ. ಉಳಿಸುವ ಮೊದಲು ಎಲ್ಲವನ್ನೂ ನೋಡುತ್ತೀರಿ.',
