  'setup.step.first_transaction_academy.w': 'ಮೊದಲ ಶುಲ್ಕ ಅಥವಾ ಇನ್‌ವಾಯ್ಸ್ ನಿಮ್ಮ ಹಣದ ಹರಿವು ಆರಂಭದಿಂದ ಕೊನೆಯವರೆಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ ಎಂದು ಸಾಬೀತುಪಡಿಸುತ್ತದೆ.',
  'setup.step.venue.t': 'ನಿಮ್ಮ ಸ್ಥಳ ಸೇರಿಸಿ',
