  'setup.step.rates.w': 'ಬೆಲೆಗಳಲ್ಲಿ ತೆರಿಗೆ ಸೇರಿದೆ. ಪೀಕ್ ಮತ್ತು ಆಫ್-ಪೀಕ್ ನಿಯಮಗಳನ್ನು ನಂತರ ಸೇರಿಸಬಹುದು.',
  'setup.step.first_transaction_venue.t': 'ನಿಮ್ಮ ಮೊದಲ ಬುಕಿಂಗ್ ತೆಗೆದುಕೊಳ್ಳಿ',
