  'setup.step.event.t': 'ನಿಮ್ಮ ಈವೆಂಟ್ ರಚಿಸಿ',
  'setup.step.event.w': 'ಕ್ರೀಡೆಗಳು, ದಿನಾಂಕಗಳು, ಸ್ಥಳ ಮತ್ತು ಸ್ವರೂಪ.',
