  "paycountry.title": "ದೇಶವಾರು ಪಾವತಿ ವಿಧಾನಗಳು",
  "paycountry.intro": "ಪಾವತಿ ವಿಧಾನವನ್ನು ಆನ್ ಅಥವಾ ಆಫ್ ಮಾಡುವ ಅಧಿಕಾರ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಅಡ್ಮಿನ್‌ಗೆ ಮಾತ್ರ ಇದೆ. ಸ್ವಿಚ್ ಇಲ್ಲದ ದೇಶದಲ್ಲಿ ಎಲ್ಲ ವಿಧಾನಗಳೂ ಆಫ್ ಆಗಿರುತ್ತವೆ. ಪ್ರತಿ ಬುಕಿಂಗ್, ತರಗತಿ, ಟಿಕೆಟ್, ನೋಂದಣಿ ಮತ್ತು ಶಾಪ್ ಚೆಕ್‌ಔಟ್‌ನಲ್ಲಿ ಆ ದೇಶಕ್ಕೆ ಆನ್ ಆಗಿರುವುದು ಮಾತ್ರ ಕಾಣುತ್ತದೆ.",
