  'es.help': 'ನೀವು ಮೌಲ್ಯಮಾಪನ ಮಾಡುವ ಚೌಕಟ್ಟನ್ನು ರಚಿಸಿ: ಸ್ತಂಭಗಳಾಗಿ ವಿಂಗಡಿಸಿದ ಮಾನದಂಡಗಳು, ತೂಕದೊಂದಿಗೆ, ಪ್ರತಿ ಹಂತ ನಡವಳಿಕೆಯಲ್ಲಿ ಹೇಗೆ ಕಾಣುತ್ತದೆ, ಗುರಿ ಮತ್ತು ಸಂಗ್ರಹಿಸಬೇಕಾದ ಸಾಕ್ಷ್ಯ. ನಿಮ್ಮ ಕ್ರೀಡೆಗಳ ಪ್ರಮಾಣಿತ ಹಾಳೆಗಳನ್ನು ನಿಮಗಾಗಿ ಸೇರಿಸಲಾಗುತ್ತದೆ; ಅವನ್ನು ಬದಲಾಯಿಸಿ ಅಥವಾ ನಕಲಿಸಿ. ಉಳಿಸಿದರೆ ಹೊಸ ಆವೃತ್ತಿ ಆಗುತ್ತದೆ, ಈಗಾಗಲೇ ಹಂಚಿದ ಮೌಲ್ಯಮಾಪನಗಳು ಅಂಕ ನೀಡಿದ ಆವೃತ್ತಿಯಲ್ಲೇ ಇರುತ್ತವೆ.',
