  'aco.src.body': 'ಸಿಬ್ಬಂದಿ ವೆಚ್ಚ ಅನುಮೋದಿತ ಪೇರೋಲ್‌ನಿಂದ ಮತ್ತು ಸ್ಥಳದ ವೆಚ್ಚ ಖಚಿತಪಡಿಸಿದ ಸ್ಥಳ ಬುಕಿಂಗ್‌ಗಳಿಂದ ಬರುತ್ತದೆ. ಒಂದು ಕಾರ್ಯಕ್ರಮಕ್ಕೆ ಇವು ಇಲ್ಲದಿದ್ದಾಗ ಮಾತ್ರ ಕೈಯಾರೆ ವೆಚ್ಚ ನಮೂದುಗಳನ್ನು ಬಳಸಲಾಗುತ್ತದೆ.',
  'aco.src.unpriced': '{n} ಅನುಮೋದಿತ ಟೈಮ್‌ಶೀಟ್‌ಗಳಿಗೆ ವೇತನ ನಿಯಮ ಇಲ್ಲ, ಆದ್ದರಿಂದ ಅವುಗಳ ವೆಚ್ಚವನ್ನು ಲೆಕ್ಕಿಸಿಲ್ಲ.',
  'aco.src.unbooked': '{n} ಸೆಷನ್‌ಗಳಿಗೆ ಸ್ಥಳ ಬುಕಿಂಗ್ ಇಲ್ಲ, ಆದ್ದರಿಂದ ಅವುಗಳ ಸ್ಥಳ ವೆಚ್ಚವನ್ನು ಲೆಕ್ಕಿಸಿಲ್ಲ.',
  'aco.src.superseded': '{n} ಕೈಯಾರೆ ನಮೂದುಗಳನ್ನು ಪಕ್ಕಕ್ಕಿಡಲಾಗಿದೆ, ಏಕೆಂದರೆ ಪೇರೋಲ್ ಅಥವಾ ಬುಕಿಂಗ್ ಅವನ್ನು ಈಗಾಗಲೇ ಒಳಗೊಂಡಿದೆ.',
  'aco.costs.intro': 'ಇವು P&L ಗಾಗಿ ನಿರ್ವಹಣಾ-ಲೆಕ್ಕಪತ್ರ ಸಾಲುಗಳು (ಮೈದಾನ ಬಾಡಿಗೆ, ಉಪಕರಣ, ಓವರ್‌ಹೆಡ್‌ನ ಪಾಲು). ಇವು ಪಾವತಿಗಳು ಅಥವಾ ಇನ್‌ವಾಯ್ಸ್‌ಗಳಲ್ಲ, ಹಣ ಚಲಿಸುವುದಿಲ್ಲ. ಸಿಬ್ಬಂದಿ ಮತ್ತು ಸ್ಥಳದ ವೆಚ್ಚವನ್ನು ಅನುಮೋದಿತ ಪೇರೋಲ್ ಮತ್ತು ಖಚಿತ ಬುಕಿಂಗ್‌ಗಳಿಂದ ಓದಲಾಗುತ್ತದೆ; ಅವು ಇಲ್ಲದಿದ್ದಾಗ ಮಾತ್ರ ಇಲ್ಲಿ ನಮೂದಿಸಿ. ನಮೂದುಗಳನ್ನು ಎಂದಿಗೂ ಬದಲಿಸುವುದಿಲ್ಲ: ರದ್ದುಪಡಿಸಿ ಮತ್ತೆ ಸೇರಿಸಿ.',
