  'guide.students.title': 'ವಿದ್ಯಾರ್ಥಿಗಳನ್ನು ಆಹ್ವಾನಿಸಿ',
  'guide.classes.title': 'ತರಗತಿಗಳನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಿ',
  'guide.tax.title': 'ತೆರಿಗೆ ಹೊಂದಿಸಿ',
  'guide.revenue.title': 'ಆದಾಯ ಹಂಚಿಕೊಳ್ಳಿ',
  'guide.reports.title': 'ವರದಿಗಳನ್ನು ನೋಡಿ',
  'guide.create.why': 'ಉಳಿದೆಲ್ಲವೂ ಸಂಸ್ಥೆಗೆ ಜೋಡಿಸಲ್ಪಟ್ಟಿವೆ, ಆದ್ದರಿಂದ ಇಲ್ಲಿಂದ ಪ್ರಾರಂಭಿಸಿ. ನೀವು ಅದರ ಮಾಲೀಕರಾಗುತ್ತೀರಿ.',
  'guide.venues.why': 'ಸೆಷನ್‌ಗಳು, ಕೋರ್ಟ್‌ಗಳು ಮತ್ತು ಶುಲ್ಕಗಳು ಸ್ಥಳಕ್ಕೆ ಜೋಡಿಸಲ್ಪಟ್ಟಿವೆ, ಆದ್ದರಿಂದ ಕಾರ್ಯಕ್ರಮ ಯೋಜಿಸುವ ಮೊದಲು ತರಬೇತಿ ಸ್ಥಳಗಳನ್ನು ಸೇರಿಸಿ.',
  'guide.staff.why': 'ತರಬೇತುದಾರರು, ಫ್ರಂಟ್ ಡೆಸ್ಕ್ ಮತ್ತು ಹಣಕಾಸಿಗೆ ಪ್ರತ್ಯೇಕ ಪ್ರವೇಶ ನೀಡಿ. ಪ್ರತಿಯೊಬ್ಬರೂ ತಮ್ಮ ಪಾತ್ರಕ್ಕೆ ಬೇಕಾದುದನ್ನು ಮಾತ್ರ ನೋಡುತ್ತಾರೆ.',
  'guide.suppliers.why': 'ನಿರ್ವಹಣಾ ಗುತ್ತಿಗೆದಾರರು ಮತ್ತು ಕಿಟ್ ಪೂರೈಕೆದಾರರನ್ನು ಒಂದೇ ಸ್ಥಳದಲ್ಲಿ ಇರಿಸಿ, ಅವರು ಸೇವೆ ನೀಡುವ ಸ್ಥಳಗಳಿಗೆ ಜೋಡಿಸಿ, ವಿನಂತಿಗಳನ್ನು ಪೂರ್ಣಗೊಳ್ಳುವವರೆಗೆ ಟ್ರ್ಯಾಕ್ ಮಾಡಿ.',
  'guide.programmes.why': 'ಕುಟುಂಬಗಳು ಖರೀದಿಸುವುದು ಕಾರ್ಯಕ್ರಮ: ತಂಡ, ಟರ್ಮ್ ಕೋರ್ಸ್ ಅಥವಾ ಶಿಬಿರ, ಬೆಲೆ ಮತ್ತು ಸ್ಥಾನಗಳೊಂದಿಗೆ.',
  'guide.coaches.why': 'ತರಬೇತುದಾರರನ್ನು ಸಿಬ್ಬಂದಿ, ಗುತ್ತಿಗೆದಾರ ಅಥವಾ ಆದಾಯ-ಪಾಲುದಾರರಾಗಿ ಕರೆತಂದು, ನಿಯಮಗಳನ್ನು ಲಿಖಿತವಾಗಿ ಒಪ್ಪಿಕೊಳ್ಳಿ.',
  'guide.students.why': 'ವಿಚಾರಣೆಯಿಂದ ದಾಖಲಾತಿಯವರೆಗೆ ಜನರನ್ನು ಕರೆದೊಯ್ಯಿರಿ. ಮಕ್ಕಳ ಪರವಾಗಿ ಪೋಷಕರು ಅಥವಾ ಪಾಲಕರು ಒಪ್ಪಿಗೆ ನೀಡುತ್ತಾರೆ.',
  'guide.classes.why': 'ಇಂದು ಮತ್ತು ವಾರವನ್ನು ಒಂದೇ ನೋಟದಲ್ಲಿ ನೋಡಿ, ಹಾಜರಾತಿ ದಾಖಲಿಸಿ, ಮೇಕ್-ಅಪ್ ಮತ್ತು ರದ್ದತಿಗಳು ಕಾಣುವಂತೆ ಇರಿಸಿ.',
  'guide.tax.why': 'ಸಂಗ್ರಹಿಸಿದ ಮತ್ತು ಪಾವತಿಸಿದ ತೆರಿಗೆಯನ್ನು, ನಿಮ್ಮ ತೆರಿಗೆ ನಿಯಮಗಳು ಮತ್ತು ಇನ್‌ವಾಯ್ಸ್‌ನ ತೆರಿಗೆ ವಿವರಗಳೊಂದಿಗೆ ತಿಳಿಯಿರಿ.',
  'guide.revenue.why': 'ತರಬೇತುದಾರರೊಂದಿಗೆ ಹಣ ಹೇಗೆ ಹಂಚಲ್ಪಡುತ್ತದೆ ಮತ್ತು ಹಂಚಿಕೆಯ ವೆಚ್ಚಗಳು ಕಾರ್ಯಕ್ರಮಗಳಲ್ಲಿ ಹೇಗೆ ವಿಭಜನೆಯಾಗುತ್ತವೆ ಎಂದು ನಿರ್ಧರಿಸಿ.',
  'guide.reports.why': 'ಕಾರ್ಯನಿರ್ವಾಹಕ ಮುಖಪುಟದಲ್ಲಿ ಫಲಿತಾಂಶ, ಉಳಿಸಿಕೊಳ್ಳುವಿಕೆ, ಹಣಕಾಸು ಆರೋಗ್ಯ ಮತ್ತು ಪಾಲುದಾರರನ್ನು ನೋಡಿ, ಬೇಕಾದುದನ್ನು ರಫ್ತು ಮಾಡಿ.',
  'dp.tab': 'ಅಭಿವೃದ್ಧಿ ಯೋಜನೆಗಳು',
  'dp.title': 'ಕ್ರೀಡಾಪಟು ಅಭಿವೃದ್ಧಿ ಯೋಜನೆಗಳು',
  'dp.subtitle': 'ತಾಂತ್ರಿಕ, ತಂತ್ರಗಾರಿಕೆ, ದೈಹಿಕ, ಮಾನಸಿಕ, ಶೈಕ್ಷಣಿಕ ಮತ್ತು ವೈಯಕ್ತಿಕ ಕ್ಷೇತ್ರಗಳಲ್ಲಿ ಪ್ರತಿ ಕ್ರೀಡಾಪಟುವಿಗೆ ಒಂದು ಋತುವಿನ ಯೋಜನೆ. ಪುರಾವೆಯನ್ನು ಅದರ ಸ್ವಂತ ದಾಖಲೆಯಿಂದ ಓದಲಾಗುತ್ತದೆ; ಯಾವುದನ್ನೂ ನಕಲಿಸಿ ಅಥವಾ ಒಂದು ಸ್ಕೋರ್ ಆಗಿ ಸಂಯೋಜಿಸಲಾಗುವುದಿಲ್ಲ.',
  'dp.family_subtitle': 'ನಿಮ್ಮ ಅಕಾಡೆಮಿ ನಿಮ್ಮೊಂದಿಗೆ ಇಟ್ಟುಕೊಳ್ಳುವ ಋತುವಿನ ಯೋಜನೆ: ಏನನ್ನು ಅಭ್ಯಾಸ ಮಾಡಲಾಗುತ್ತಿದೆ, ಕಾರ್ಯಗಳು, ಮತ್ತು ನೀವು ಓದಿ ಪ್ರತಿಕ್ರಿಯಿಸಬಹುದಾದ ಪರಿಶೀಲನೆಗಳು.',
  'dp.new_plan': 'ಹೊಸ ಯೋಜನೆ',
  'dp.create': 'ಯೋಜನೆ ರಚಿಸಿ',
  'dp.created': 'ಯೋಜನೆ ರಚಿಸಲಾಗಿದೆ. ಉದ್ದೇಶಗಳನ್ನು ಸೇರಿಸಿ, ತಂಡಕ್ಕೆ ಹೆಸರಿಡಿ, ನಂತರ ಸಕ್ರಿಯಗೊಳಿಸಿ.',
  'dp.new_notice': 'ಒಂದು ಯೋಜನೆಯು ಒಂದು ಋತುವಿಗಾಗಿ ಒಬ್ಬ ಕ್ರೀಡಾಪಟುವಿನ ಸುತ್ತಲಿನ ಜನರನ್ನು ಸಂಯೋಜಿಸುತ್ತದೆ. ಇದು ತರಬೇತಿ, ಹಾಜರಾತಿ, ಶಾಲೆ ಮತ್ತು ಪಥದ ದಾಖಲೆಗಳಿಗೆ ಲಿಂಕ್ ಆಗುತ್ತದೆ; ಅವುಗಳನ್ನು ಎಂದಿಗೂ ನಕಲಿಸುವುದಿಲ್ಲ.',
  'dp.search': 'ಕ್ರೀಡಾಪಟು ಅಥವಾ ಋತುವನ್ನು ಹುಡುಕಿ',
  'dp.all': 'ಎಲ್ಲವೂ',
  'dp.all_plans': 'ಎಲ್ಲಾ ಯೋಜನೆಗಳು',
  'dp.none': 'ಇನ್ನೂ ಯಾವುದೇ ಅಭಿವೃದ್ಧಿ ಯೋಜನೆಗಳಿಲ್ಲ',
  'dp.none_sub': 'ದಾಖಲಾದ ಕ್ರೀಡಾಪಟುವಿಗೆ ಯೋಜನೆ ತೆರೆಯಿರಿ: ಋತು, ಹೊಣೆಗಾರ ಮುಖ್ಯಸ್ಥ ಮತ್ತು ಪ್ರತಿ ಕ್ಷೇತ್ರದ ಉದ್ದೇಶಗಳನ್ನು ಆರಿಸಿ.',
  'dp.none_sub_coach': 'ನಿಮ್ಮ ಗುಂಪುಗಳಲ್ಲಿನ ಕ್ರೀಡಾಪಟುವಿಗೆ ಯೋಜನೆ ತೆರೆಯಿರಿ. ನೀವು ಅದರ ಮುಖ್ಯಸ್ಥರಾಗುತ್ತೀರಿ ಮತ್ತು ಇತರ ತಜ್ಞರನ್ನು ಆಹ್ವಾನಿಸಬಹುದು.',
  'dp.none_match': 'ಯಾವುದೇ ಯೋಜನೆ ಹೊಂದಿಕೆಯಾಗುತ್ತಿಲ್ಲ',
  'dp.none_match_sub': 'ಬೇರೆ ಹೆಸರು ಅಥವಾ ಸ್ಥಿತಿಯನ್ನು ಪ್ರಯತ್ನಿಸಿ.',
