  "guide.content.why": "ನಿಮ್ಮ ಅನುಮೋದಿತ ಕಾರ್ಯವಿಧಾನ, ಪಠ್ಯಕ್ರಮ, ಡ್ರಿಲ್‌ಗಳು ಮತ್ತು ಸೂಕ್ಷ್ಮ ಕೋರ್ಸ್‌ಗಳನ್ನು ಪರವಾನಗಿ ಪ್ಯಾಕ್ ಆಗಿ ಪ್ಯಾಕೇಜ್ ಮಾಡಿ; ಇದರಿಂದ ಸಂಯೋಜಿತ ಮತ್ತು ಸ್ವತಂತ್ರ ಸಂಸ್ಥೆಗಳು ತಮ್ಮ ತರಬೇತುದಾರರಿಗೆ ಸೀಟ್‌ಗಳನ್ನು ಖರೀದಿಸಬಹುದು, ಮತ್ತು ನೀವು ಹಕ್ಕುಗಳು, ಆವೃತ್ತಿಗಳು ಮತ್ತು ಆದಾಯದ ದಾಖಲೆಯನ್ನು ಉಳಿಸಿಕೊಳ್ಳುತ್ತೀರಿ.",
  "cl.sess.title": "ಪರವಾನಗಿ ಪಡೆದ ವಿಷಯ",
  "cl.sess.help": "ನಿಮ್ಮ ಸಂಸ್ಥೆ ಪರವಾನಗಿ ಪಡೆದ ಪ್ಯಾಕ್‌ಗಳ ಐಟಂಗಳು, ಈ ಸೆಷನ್‌ನಲ್ಲಿ ಬಳಸಲಾಗುತ್ತಿದೆ. ಐಟಂ ಅನ್ನು ಲಿಂಕ್ ಮಾಡಿ, ನಂತರ ಅದನ್ನು ನಿಮ್ಮ ಸ್ವಂತ ಯೋಜನೆಗೆ ಸೇರಿಸಿ.",
  "cl.sess.add": "ಪರವಾನಗಿ ಪಡೆದ ವಿಷಯ ಸೇರಿಸಿ",
  "cl.sess.pick": "ನೀವು ಬಳಸಬಹುದಾದ ಐಟಂಗಳು",
  "cl.sess.added": "ಈ ಸೆಷನ್‌ಗೆ ಸೇರಿಸಲಾಗಿದೆ",
  "cl.sess.empty": "ಪರವಾನಗಿ ಪಡೆದ ವಿಷಯ ಲಿಂಕ್ ಆಗಿಲ್ಲ",
  "cl.sess.empty_pick": "ನಿಮ್ಮ ಸಂಸ್ಥೆ ಪರವಾನಗಿ ಪಡೆದ ಪ್ಯಾಕ್‌ನಿಂದ ಡ್ರಿಲ್, ಪಠ್ಯಕ್ರಮ ಅಥವಾ ಮೈಕ್ರೋ-ಕೋರ್ಸ್ ಅನ್ನು ಲಿಂಕ್ ಮಾಡಿ.",
  "cl.sess.empty_none": "ನಿಮ್ಮ ಸಂಸ್ಥೆಯಲ್ಲಿ ನೀವು ಸೀಟ್ ಹೊಂದಿರುವ ಪರವಾನಗಿ ಪಡೆದ ವಿಷಯ ಇನ್ನೂ ಇಲ್ಲ. ವಿಷಯ ವಿಭಾಗದಲ್ಲಿ ಮಾರುಕಟ್ಟೆಯನ್ನು ಬ್ರೌಸ್ ಮಾಡಿ.",
  "cl.sess.withdrawn": "ಹಿಂಪಡೆಯಲಾಗಿದೆ",
  "cl.sess.locked_hint": "ಈ ಪರವಾನಗಿ ಸಕ್ರಿಯವಾಗಿಲ್ಲದ ಕಾರಣ ವಿಷಯ ಲಾಕ್ ಆಗಿದೆ. ನವೀಕರಿಸಲು ನಿಮ್ಮ ಅಕಾಡೆಮಿ ನಿರ್ವಾಹಕರನ್ನು ಕೇಳಿ. ಈಗಾಗಲೇ ರಚಿಸಿದ ಯೋಜನಾ ಬ್ಲಾಕ್‌ಗಳು ನಿಮ್ಮ ದಾಖಲೆಯಲ್ಲಿ ಉಳಿಯುತ್ತವೆ.",
  "cl.sess.no_seat": "ಈ ಪ್ಯಾಕ್‌ಗೆ ನೀವು ಸೀಟ್ ಹೊಂದಿಲ್ಲ.",
  "cl.sess.unlink": "ಲಿಂಕ್ ತೆಗೆಯಿರಿ",
  "cl.sess.unlinked": "ಈ ಸೆಷನ್‌ನಿಂದ ಲಿಂಕ್ ತೆಗೆಯಲಾಗಿದೆ",
  "cl.sess.load": "ನನ್ನ ಯೋಜನೆಗೆ ಸೇರಿಸಿ",
  "cl.sess.load_hint": "ಡ್ರಿಲ್‌ಗಳು, ಉದ್ದೇಶಗಳು ಮತ್ತು ಮೈಕ್ರೋ-ಕೋರ್ಸ್‌ಗಳನ್ನು ನಿಮ್ಮ ಸ್ವಂತ ತರಬೇತಿ ಯೋಜನೆಗೆ ಬ್ಲಾಕ್‌ಗಳಾಗಿ ಸೇರಿಸುತ್ತದೆ. ಪರವಾನಗಿ ಆಫ್‌ಲೈನ್ ಪ್ರತಿಗಳಿಗೆ ಅವಕಾಶ ನೀಡಿದರೆ ಪಠ್ಯವನ್ನು ಬ್ಲಾಕ್‌ಗೆ ನಕಲಿಸಲಾಗುತ್ತದೆ, ಇಲ್ಲದಿದ್ದರೆ ಬ್ಲಾಕ್ ಪರವಾನಗಿ ಪಡೆದ ಐಟಂಗೆ ಲಿಂಕ್ ಆಗುತ್ತದೆ.",
  "cl.sess.loaded": "ನಿಮ್ಮ ಯೋಜನೆಗೆ {n} ಬ್ಲಾಕ್‌ಗಳನ್ನು ಸೇರಿಸಲಾಗಿದೆ",
