  'cap.intro': 'ನಿಮ್ಮ ನಿಜವಾದ ಅವಧಿಗಳು, ವೇತನ, ಬುಕಿಂಗ್‌ಗಳು ಮತ್ತು ಬೆಳವಣಿಗೆಯ ಮಾರ್ಗಗಳ ಆಧಾರದ ಮೇಲೆ ದಾಖಲಾತಿ, ಬಡ್ತಿ, ಹೊಸ ತಂಡ, ಸ್ಥಳ ಮತ್ತು ತರಬೇತುದಾರರ ಕುರಿತು “ಹೀಗಾದರೆ” ಪರೀಕ್ಷಿಸಿ. ನಿಮ್ಮ ಅಕಾಡೆಮಿಯಲ್ಲಿ ಏನೂ ಬದಲಾಗುವುದಿಲ್ಲ.',
