  'guide.placement.title': 'Manage placement pathways',
  'guide.placement.why': 'Give every graduating athlete a consented bridge from academy progression to university, scholarship and professional opportunities, managed by a placement advisor with an auditable funnel, evidence checklist, reference requests and revocable institution sharing.',
  'guide.placement.s1': 'Open Academy, then Placement, and tap Add opportunity for an enrolled athlete.',
  'guide.placement.s2': 'Choose the type (university place, scholarship, grant or professional contract), set the institution, sport, deadline and intake year.',
  'guide.placement.s3': 'Build the evidence checklist: add items for academic transcript, sport CV, performance video, references and any passport or ranking documents.',
  'guide.placement.s4': 'Request references from coaches, academic coordinators or other referees and track their submission status.',
  'guide.placement.s5': 'Ask the athlete (or their guardian for under-18s) to grant the institution access to specific evidence fields. They choose exactly what to share and can revoke at any time.',
  'guide.placement.s6': 'Advance the opportunity through its stages — identified, eligibility check, evidence gathering, applied, offer received, outcome — as the process progresses.',
  'guide.placement.s7': 'Link a sponsorship award to the opportunity for attribution tracking across the finance module.',
  'guide.placement.s8': 'Use the Action Queue to triage urgent items: references due, missing evidence and pending guardian consents. Use Analytics for seasonal outcome and scholarship reports.',
  'arp.nav': 'ವರದಿಗಳು',
  'arp.title': 'ವರದಿಗಳು ಮತ್ತು ಪ್ಯಾಕ್‌ಗಳು',
  'arp.subtitle': 'ಬ್ರಾಂಡ್ ಮಾಡಿದ, ನಿರ್ದಿಷ್ಟ ಸಮಯದ ಪ್ಯಾಕ್‌ಗಳು. ಅಕಾಡೆಮಿಯ ಹೊರಗಿನ ಯಾರಾದರೂ ನೋಡುವ ಮೊದಲು ಎರಡನೇ ವ್ಯಕ್ತಿ ಪ್ರತಿಯೊಂದನ್ನೂ ಅನುಮೋದಿಸುತ್ತಾರೆ.',
  'arp.tab.packs': 'ಪ್ಯಾಕ್‌ಗಳು',
  'arp.tab.queue': 'ಪರಿಶೀಲನಾ ಸರದಿ',
  'arp.tab.schedules': 'ವೇಳಾಪಟ್ಟಿಗಳು',
  'arp.tab.issued': 'ವಿತರಿಸಿದವು',
  'arp.k.awaiting': 'ಪರಿಶೀಲನೆಗೆ ಕಾಯುತ್ತಿದೆ',
  'arp.k.overdue': '{n} ತಡವಾಗಿವೆ',
  'arp.k.issued': 'ವಿತರಿಸಿದವು, ಕಳೆದ 90 ದಿನ',
  'arp.k.scheduled': 'ನಿಗದಿತ',
  'arp.k.next': 'ಮುಂದಿನದು {date}',
  'arp.k.revoked': 'ಹಿಂಪಡೆದವು',
  'arp.k.history_kept': 'ಇತಿಹಾಸ ಉಳಿಸಲಾಗಿದೆ',
  'arp.kind.progress': 'ಅಭಿವೃದ್ಧಿ ಮತ್ತು ಮೌಲ್ಯಮಾಪನ ವರದಿ',
  'arp.kind.term': 'ಅವಧಿ ವರದಿ',
  'arp.kind.management': 'ಮಂಡಳಿ ನಿರ್ವಹಣಾ ಪ್ಯಾಕ್',
  'arp.kind.finance': 'ಲಾಭ-ನಷ್ಟ ಪ್ಯಾಕ್',
  'arp.kind.campus': 'ಕ್ಯಾಂಪಸ್ ಗುಣಮಟ್ಟ ಪ್ಯಾಕ್',
  'arp.scope.athlete': 'ಕ್ರೀಡಾಪಟು',
  'arp.scope.campus': 'ಕ್ಯಾಂಪಸ್',
  'arp.scope.academy': 'ಅಕಾಡೆಮಿ',
  'arp.aud.progress': 'ಅಕಾಡೆಮಿ ಮಾಲೀಕರು, ಅಡ್ಮಿನ್‌ಗಳು, ಕ್ರೀಡಾಪಟುವಿನ ತರಬೇತುದಾರ, ಕ್ರೀಡಾಪಟು ಮತ್ತು ಪರಿಶೀಲಿತ ಪಾಲಕರು ಓದಬಹುದು. ಹಣಕಾಸು, ವೈದ್ಯಕೀಯ ಅಥವಾ ಕಲ್ಯಾಣ ಟಿಪ್ಪಣಿಗಳು, ತರಬೇತುದಾರ ಮತ್ತು ಸಿಬ್ಬಂದಿಯ ಖಾಸಗಿ ಅಭಿಪ್ರಾಯ ಎಂದಿಗೂ ಸೇರುವುದಿಲ್ಲ.',
  'arp.aud.term': 'ಅಭಿವೃದ್ಧಿ ವರದಿಯ ಅದೇ ಓದುಗರು. ಅವಧಿಯ ಹಾಜರಾತಿ ಮತ್ತು ಹಂಚಿದ್ದರೆ ಶಾಲೆಯ ಬ್ಯಾಂಡ್ ಸೇರುತ್ತದೆ. ಶಾಲೆಯ ಅಂಕಗಳನ್ನು ಎಂದಿಗೂ ಮುದ್ರಿಸುವುದಿಲ್ಲ.',
  'arp.aud.management': 'ಅಕಾಡೆಮಿ ಮಾಲೀಕರು ಮತ್ತು ಅಡ್ಮಿನ್‌ಗಳು ಮಾತ್ರ ಓದಬಹುದು. 3ಕ್ಕಿಂತ ಕಡಿಮೆ ಗುಂಪುಗಳನ್ನು ಸಂಖ್ಯೆಯಾಗಿ ಮುದ್ರಿಸುವುದಿಲ್ಲ. ಕಾನೂನು, ವೈದ್ಯಕೀಯ ಅಥವಾ ತರಬೇತುದಾರರ ಖಾಸಗಿ ವಿವರ ಇಲ್ಲ.',
  'arp.aud.finance': 'ಅಕಾಡೆಮಿ ಮಾಲೀಕರು, ಅಡ್ಮಿನ್‌ಗಳು ಮತ್ತು ಹಣಕಾಸು ಮಾತ್ರ ಓದಬಹುದು. ನಿರ್ವಹಣಾ ಲೆಕ್ಕಗಳು, ಕಾನೂನುಬದ್ಧ ಅಥವಾ ಲೆಕ್ಕಪರಿಶೋಧಿತ ಅಲ್ಲ. ತರಬೇತಿ ಅಥವಾ ವೈದ್ಯಕೀಯ ಡೇಟಾ ಇಲ್ಲ.',
  'arp.aud.campus': 'ಅಕಾಡೆಮಿ ಮಾಲೀಕರು ಮತ್ತು ಅಡ್ಮಿನ್‌ಗಳು ಮಾತ್ರ ಓದಬಹುದು. ಒಂದು ಕ್ಯಾಂಪಸ್: ಜನರು, ಕಾರ್ಯಾಚರಣೆ, ಸಿಬ್ಬಂದಿ, ಹಣಕಾಸು. 3ಕ್ಕಿಂತ ಕಡಿಮೆ ಗುಂಪುಗಳನ್ನು ಸಂಖ್ಯೆಯಾಗಿ ಮುದ್ರಿಸುವುದಿಲ್ಲ.',
  'arp.basis.progress': 'ಕ್ರೀಡಾಪಟುವಿಗೆ ಸುರಕ್ಷಿತ ಪ್ರಗತಿ ನೋಟ: ತರಬೇತುದಾರರ ಮೌಲ್ಯಮಾಪನ, ಅಕಾಡೆಮಿ ಹಾಜರಾತಿ ಮತ್ತು ಅನುಮೋದಿತ ಅಧಿಕೃತ ಫಲಿತಾಂಶಗಳು ಪ್ರತ್ಯೇಕವಾಗಿ.',
  'arp.basis.term': 'ಅವಧಿಯ ಪ್ರಗತಿ ನೋಟ, ಅವಧಿಯ ಹಾಜರಾತಿ ಮತ್ತು ಹಂಚಿದ್ದರೆ ಶಾಲೆಯ ಬ್ಯಾಂಡ್. ಯಾವುದನ್ನೂ ಒಂದೇ ಸ್ಕೋರ್ ಆಗಿ ಸೇರಿಸುವುದಿಲ್ಲ.',
  'arp.basis.management': 'ಎಕ್ಸಿಕ್ಯೂಟಿವ್ ಹೋಮ್‌ನ ಅದೇ ಅಂಕಿಅಂಶಗಳಿಂದ ನಿರ್ವಹಣಾ ನೋಟ. ಕಾನೂನುಬದ್ಧ ಲೆಕ್ಕಗಳಲ್ಲ.',
  'arp.basis.finance': 'ಹಣಕಾಸು ಲೆಡ್ಜರ್, ಅನುಮೋದಿತ ವೇತನಪಟ್ಟಿ ಮತ್ತು ದೃಢಪಡಿಸಿದ ಸ್ಥಳ ಬುಕಿಂಗ್‌ಗಳಿಂದ ನಿರ್ವಹಣಾ ಲೆಕ್ಕಗಳು. ಕಾನೂನುಬದ್ಧ ಅಥವಾ ಲೆಕ್ಕಪರಿಶೋಧಿತ ಅಲ್ಲ.',
  'arp.basis.campus': 'ಎಕ್ಸಿಕ್ಯೂಟಿವ್ ಹೋಮ್ ಮತ್ತು ಲಾಭ-ನಷ್ಟದ ಅದೇ ಅಂಕಿಅಂಶಗಳಿಂದ ಒಂದು ಕ್ಯಾಂಪಸ್‌ನ ನಿರ್ವಹಣಾ ನೋಟ.',
