  'guide.accreditation.title': 'ಮಾನ್ಯತೆ ಮತ್ತು ಆಡಿಟ್‌ಗಳನ್ನು ನಿರ್ವಹಿಸಿ',
  'guide.accreditation.why': 'ನಿಮ್ಮ ಅಕಾಡೆಮಿ ಹೊಂದಿರುವ ಪ್ರತಿ ಬಾಹ್ಯ ಮಾನ್ಯತೆ, ಪರವಾನಗಿ ಮತ್ತು ಗುಣಮಟ್ಟ ಮುದ್ರೆಯನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಿ, ಪ್ರತಿಯೊಂದರ ಸಾಕ್ಷ್ಯವನ್ನು ನೀವು ಈಗಾಗಲೇ ನಿರ್ವಹಿಸುವ ದಾಖಲೆಗಳಿಗೆ ಜೋಡಿಸಿ, ಮತ್ತು ಗುಟ್ಟಾಗಿ ಬದಲಾಯಿಸಲಾಗದ ಪತ್ತೆಗಳು ಹಾಗೂ ಸರಿಪಡಿಸುವ ಕ್ರಮಗಳೊಂದಿಗೆ ಆಡಿಟ್‌ಗಳನ್ನು ನಡೆಸಿ.',
  'guide.accreditation.s1': 'ಅಕಾಡೆಮಿ ತೆರೆದು, ನಂತರ ಮಾನ್ಯತೆ ತೆರೆಯಿರಿ ಮತ್ತು ಚೌಕಟ್ಟು ಸೇರಿಸಲು ಹೊಂದಿಸಿ ಒತ್ತಿರಿ: ಮಾನ್ಯತೆ ನೀಡುವ ಸಂಸ್ಥೆ, ಪ್ರಕಾರ, ಹಂತ, ಮಾಲೀಕ, ನವೀಕರಣ ಚಕ್ರ ಮತ್ತು ಮುಂಚಿನ ನೆನಪಿನ ಅವಧಿ.',
  'guide.accreditation.s2': 'ಚೌಕಟ್ಟು ತೆರೆದು, ಸಾಕ್ಷ್ಯ ಆಯ್ಕೆಮಾಡಿ, ಅದಕ್ಕೆ ಬೇಕಾದುದನ್ನು ಸೇರಿಸಿ, ನಂತರ ತರಬೇತುದಾರರ ಪ್ರಮಾಣಪತ್ರಗಳು ಮತ್ತು ಅನುಸರಣೆ ದಾಖಲೆಗಳನ್ನು ಜೋಡಿಸಿ. ಏನನ್ನೂ ನಕಲಿಸುವುದಿಲ್ಲ, ಮಾನ್ಯತೆಯನ್ನು ನೇರವಾಗಿ ಓದಲಾಗುತ್ತದೆ.',
  'guide.accreditation.s3': 'ಆಡಿಟ್ ನಿಗದಿಪಡಿಸಿ ಒತ್ತಿ, ಪ್ರಕಾರ, ದಿನಾಂಕ ಮತ್ತು ಪರಿಶೀಲಿಸಬೇಕಾದ ಕ್ಷೇತ್ರಗಳನ್ನು ಆರಿಸಿ, ಬೇಕಿದ್ದರೆ ಪರಿವೀಕ್ಷಕರನ್ನು ಹೆಸರಿಸಿ; ಅವರಿಗೆ ಆ ಆಡಿಟ್ ಮಾತ್ರ ಕಾಣಿಸುತ್ತದೆ.',
  'guide.accreditation.s4': 'ಪ್ರತಿ ಪತ್ತೆಯನ್ನು ಅದರ ತೀವ್ರತೆ ಮತ್ತು ಸರಿಪಡಿಸುವ ಕ್ರಮಗಳೊಂದಿಗೆ ದಾಖಲಿಸಿ, ಪ್ರತಿ ಕ್ರಮಕ್ಕೂ ಮಾಲೀಕ ಮತ್ತು ಅಂತಿಮ ದಿನಾಂಕ ನೀಡಿ, ಕೆಲಸ ಮುಗಿದಂತೆ ಪೂರ್ಣಗೊಂಡಿದೆ ಎಂದು ಗುರುತಿಸಿ.',
  'guide.accreditation.s5': 'ಎಲ್ಲಾ ಹೆಚ್ಚು ಮತ್ತು ಮಧ್ಯಮ ಪತ್ತೆಗಳು ಪರಿಹಾರವಾದ ನಂತರ ಮರುಸಲ್ಲಿಸಿ, ನಂತರ ಪರಿವೀಕ್ಷಕರ ನಿರ್ಧಾರ ದಾಖಲಿಸಿ. ಪ್ರತಿ ಹಂತವೂ ಲಾಕ್ ಆದ ಜಾಡಿನಲ್ಲಿ ಉಳಿಯುತ್ತದೆ.',
