  'inc.a_none_sub': 'ಮೊದಲು ಪಥದ ಹಂತಕ್ಕೆ ಒಂದು ಮೌಲ್ಯಮಾಪನವನ್ನು ದಾಖಲಿಸಿ, ನಂತರ ಇಲ್ಲಿ ಅದನ್ನು ಹೊಂದಿಸಿ.',
  'inc.a_title': 'ಹೊಂದಿಸಿದ, ತರಬೇತುದಾರರ ನೇತೃತ್ವದ ಮೌಲ್ಯಮಾಪನ',
  'inc.a_note': 'ಪ್ರತಿ ಆಯಾಮವನ್ನು ಪದಗಳಲ್ಲಿ ವಿವರಿಸಿ. ಯಾವುದೇ ಸಂಖ್ಯೆ ಅಥವಾ ಒಂದೇ ಅಂಕ ಇಲ್ಲ.',
  'inc.a_variant': 'ಪಥದ ಪರ್ಯಾಯ',
  'inc.a_dimension': 'ಆಯಾಮ {n}',
  'inc.a_add': 'ಆಯಾಮ ಸೇರಿಸಿ',
  'inc.a_note_label': 'ತರಬೇತುದಾರರ ಟಿಪ್ಪಣಿ (ಐಚ್ಛಿಕ)',
  'inc.a_save': 'ಹೊಂದಿಸಿದ ಮೌಲ್ಯಮಾಪನವನ್ನು ಉಳಿಸಿ',
  'inc.a_sign': 'ಎರಡನೇ ಮೌಲ್ಯಮಾಪಕರಾಗಿ ಸಹಿ ಮಾಡಿ',
  'inc.a_sign_a11y': 'ಈ ಹೊಂದಿಸಿದ ಮೌಲ್ಯಮಾಪನಕ್ಕೆ ಎರಡನೇ ಮೌಲ್ಯಮಾಪಕರಾಗಿ ಸಹಿ ಮಾಡಿ',
  'inc.a_need_one': 'ಕನಿಷ್ಠ ಒಂದು ಆಯಾಮವನ್ನು ಸೇರಿಸಿ',
  'inc.a_saved': 'ಹೊಂದಿಸಿದ ಮೌಲ್ಯಮಾಪನವನ್ನು ಉಳಿಸಲಾಗಿದೆ',
  'inc.a_signed': 'ಸಹಿ ಮಾಡಲಾಗಿದೆ',
  'inc.lvl_emerging': 'ಉದಯೋನ್ಮುಖ',
  'inc.lvl_developing': 'ಬೆಳೆಯುತ್ತಿರುವ',
  'inc.lvl_secure': 'ಸ್ಥಿರ',
  'inc.lvl_exceeding': 'ನಿರೀಕ್ಷೆಗಿಂತ ಮೇಲೆ',
  'guide.inclusion.title': 'ಒಳಗೊಳ್ಳುವ ಮತ್ತು ಹೊಂದಿಕೊಳ್ಳುವ ಕಾರ್ಯಕ್ರಮಗಳನ್ನು ನಡೆಸಿ',
  'guide.inclusion.why': 'ಅಂಗವಿಕಲ ಮತ್ತು ಪ್ಯಾರಾ ಕ್ರೀಡಾಪಟುಗಳು ರೋಗನಿರ್ಣಯವನ್ನು ಬಹಿರಂಗಪಡಿಸದೆ ನಿಮ್ಮ ಕಾರ್ಯಕ್ರಮಗಳಲ್ಲಿ ಸೇರಿ ಪ್ರಗತಿ ಹೊಂದಲು ಅವಕಾಶ ನೀಡಿ: ಕಾರ್ಯಕ್ರಮ ಏನನ್ನು ನೀಡುತ್ತದೆ ಎಂಬುದನ್ನು ಹೊಂದಿಸಿ, ಪ್ರತಿ ಹೊಂದಿಕೊಳ್ಳುವ ಅವಧಿ ಸಿದ್ಧವಾಗಿದೆಯೇ ಎಂದು ಪರಿಶೀಲಿಸಿ, ಮತ್ತು ಕ್ರೀಡಾಪಟುಗಳು ತಾವು ಆಯ್ಕೆಮಾಡಿದ ಕಾರ್ಯಾಚರಣೆಯ ಅಗತ್ಯಗಳನ್ನು ಮಾತ್ರ ಹಂಚಿಕೊಳ್ಳಲಿ.',
  'guide.inclusion.s1': 'ಅಕಾಡೆಮಿ ತೆರೆಯಿರಿ, ನಂತರ ಒಳಗೊಳ್ಳುವಿಕೆ, ನಂತರ ಕಾರ್ಯಕ್ರಮ ಸಿದ್ಧತೆ, ಒಂದು ಕಾರ್ಯಕ್ರಮವನ್ನು ಆರಿಸಿ ಮತ್ತು ಯಾರು ಸೇರಬಹುದು, ಕ್ರೀಡೆಯ ಹೊಂದಾಣಿಕೆ ಟೆಂಪ್ಲೇಟ್‌ಗಳು, ನೀಡುವ ಹೊಂದಾಣಿಕೆಗಳು, ಸ್ಥಳದ ಸೌಲಭ್ಯಗಳು ಮತ್ತು ಅದಕ್ಕೆ ಬೇಕಾದ ಸಹಾಯಕರ ಅನುಪಾತವನ್ನು ಆಯ್ಕೆಮಾಡಿ.',
  'guide.inclusion.s2': 'ಅವಧಿಗಳನ್ನು ಪರಿಶೀಲಿಸಲು ಪ್ರತಿ ಸ್ಥಳದ ಪ್ರವೇಶ ಸೌಲಭ್ಯಗಳನ್ನು (ಲಿಫ್ಟ್, ಮೆಟ್ಟಿಲಿಲ್ಲದ ದಾರಿ, ಪ್ರವೇಶಿಸಬಹುದಾದ ಉಡುಪು ಬದಲಿಸುವ ಕೊಠಡಿ, ಈಜುಕೊಳದ ಹಾಯಿಸ್ಟ್) ದಾಖಲಿಸಲು ಸ್ಥಳ ವ್ಯವಸ್ಥಾಪಕರನ್ನು ಕೇಳಿ.',
  'guide.inclusion.s3': 'ಕ್ರೀಡಾಪಟುಗಳು, ಅಥವಾ ಯುವ ವ್ಯಕ್ತಿಯ ಪರಿಶೀಲಿತ ಪೋಷಕರು, ನನ್ನ ಅಕಾಡೆಮಿ, ನಂತರ ಸೌಕರ್ಯಗಳನ್ನು ತೆರೆದು, ಸಿಬ್ಬಂದಿಗೆ ಬೇಕಾದುದನ್ನು ಮಾತ್ರ, ಯಾರೊಂದಿಗೆ ಮತ್ತು ಎಲ್ಲಿಯವರೆಗೆ ಹಂಚಿಕೊಳ್ಳುತ್ತಾರೆ. ಅವರು ಯಾವುದೇ ಕ್ಷಣದಲ್ಲಿ ಅದನ್ನು ಹಿಂಪಡೆಯಬಹುದು.',
  'guide.inclusion.s4': 'ಒಳಗೊಳ್ಳುವಿಕೆ, ನಂತರ ಅವಧಿ ಸಿದ್ಧತೆ ತೆರೆಯಿರಿ, ಒಂದು ಅವಧಿಯನ್ನು ಆರಿಸಿ ಮತ್ತು ಪ್ರತಿ ಕೊರತೆಯನ್ನು ಪರಿಹರಿಸಿ: ಸ್ಥಳ, ಸಹಾಯಕರು, ಕರ್ತವ್ಯ ವ್ಯವಸ್ಥೆ ಮತ್ತು ಮುಖ್ಯ ತರಬೇತುದಾರರ ಅರ್ಹತೆ. ತರಬೇತುದಾರರು ಮತ್ತು ಸ್ಥಳದ ಸಿಬ್ಬಂದಿ ತಮ್ಮೊಂದಿಗೆ ಹಂಚಿಕೊಂಡದ್ದನ್ನು ಮಾತ್ರ ನೋಡುತ್ತಾರೆ, ಮತ್ತು ಪ್ರತಿ ನೋಟವನ್ನು ಕ್ರೀಡಾಪಟುವಿಗಾಗಿ ದಾಖಲಿಸಲಾಗುತ್ತದೆ.',
  'guide.inclusion.s5': 'ವಿವರಣಾತ್ಮಕ ಹಂತಗಳೊಂದಿಗೆ, ಎಂದಿಗೂ ಒಂದೇ ಅಂಕವಿಲ್ಲದೆ, ಹೊಂದಿಸಿದ ತರಬೇತುದಾರರ ನೇತೃತ್ವದ ಮೌಲ್ಯಮಾಪನಗಳನ್ನು ದಾಖಲಿಸಿ, ಮತ್ತು ಎರಡನೇ ಮೌಲ್ಯಮಾಪಕರಿಂದ ಸಹಿ ಮಾಡಿಸಿ. ನಿರ್ದೇಶಕರು ಅವಲೋಕನದಲ್ಲಿ ಎಣಿಕೆಗಳನ್ನು ಮಾತ್ರ ನೋಡುತ್ತಾರೆ.',


